import{_ as e,c as r,o as a,ah as s,aj as i}from"./chunks/framework.BssxmkiH.js";const g=JSON.parse('{"title":"Godrays","description":"","frontmatter":{},"headers":[],"relativePath":"godrays-settings.md","filePath":"godrays-settings.md"}'),o={name:"godrays-settings.md"};function n(d,t,l,h,y,c){return a(),r("div",null,t[0]||(t[0]=[s('<h1 id="godrays" tabindex="-1">Godrays <a class="header-anchor" href="#godrays" aria-label="Permalink to “Godrays”">​</a></h1><p><img src="'+i+'" alt="light shafts / godrays" loading="lazy"></p><p>Godrays is an intresting visual effect noticed when the light beam is obstructued by clouds or an object. The effect is controled by the settings below.</p><table tabindex="0"><thead><tr><th>Property</th><th>Function</th></tr></thead><tbody><tr><td>Enabled</td><td>Enable state of this effect. <br><br> This is a <a href="./glossary#static-parameters">static</a> and <a href="./glossary#performance-sensitive-parameters">performance sensitive</a> parameter.</td></tr><tr><td>Resolution</td><td>The resolution of the internal render textures used for god rays rendering. Lower values are fine since rays usually blurry. <br><br> This is a <a href="./glossary#static-parameters">static</a> and <a href="./glossary#performance-sensitive-parameters">performance sensitive</a> parameter.</td></tr><tr><td>Backlighting</td><td>Whether to render god rays when the sun is behind objects. This effect is quite inaccurate(especially for clouds) and not usually visually pleasing.</td></tr><tr><td>Blur Iterations</td><td>The number of blur iterations applied to the god rays. Default value of <code>2</code> is fine. Adjust only if necessary (e.g noticing banding artifacts). <br><br> This is a <a href="./glossary#performance-sensitive-parameter">performance sensitive parameter</a></td></tr><tr><td>Blur Spread</td><td>The blur spread applied to the god rays per iteration. Use the Frame Debugger to find a good balance between &#39;BlurIterations&#39; and &#39;BlurSpread&#39; depending on your performance, quality and visual requirements.</td></tr><tr><td>Day Intensity</td><td>The intensity of the rays at day time.</td></tr><tr><td>Night Intensity</td><td>The intensity of the rays at night time.</td></tr><tr><td>Contrast</td><td>The contrast of the god rays. Higher values result in more defined rays.</td></tr><tr><td>Anti-Flickering</td><td>Whether to apply a temporal filter to the god rays to reduce flickering.</td></tr><tr><td>Anti-Flickering Strength</td><td>The strength of the anti-flickering filter. Higher values result in smoother rays but more ghosting.</td></tr><tr><td>Geometry Rays Intensity</td><td>Intensity multiplier for rays on top of a geometry.</td></tr><tr><td>Geometry Rays Color</td><td>Color multiplier for rays on top of a geometry.</td></tr></tbody></table>',4)]))}const p=e(o,[["render",n]]);export{g as __pageData,p as default};
